 const portal=publication?.quoteId===quote.id&&publication.quoteVersion===quote.data.quoteVersion&&publication.publishedAt&&publication.recipient?.ownerUserId===quote.data.ownerUserId&&publication.snapshot?.id===quote.id&&publication.snapshot?.quoteVersion===quote.data.quoteVersion;
