 assert(quote.data.status==='ACCEPTED'&&quote.data.orderId===order.id&&quote.data.quoteVersion===order.data.quoteVersion&&quote.data.customerId===order.data.customerId&&lead.data.currentQuoteId===quote.id,'NEEDS_APPROVAL',{reason:'CURRENT_ACCEPTED_ORDER_SCOPE_REQUIRED'});requireLeadReviewResolved(lead);
