 assert(acceptance&&acceptance.data.orderId===order.id&&acceptance.data.customerId===order.data.customerId&&acceptance.data.quoteId===quote.id&&acceptance.data.quoteVersion===quote.data.quoteVersion&&acceptance.data.commercialSnapshot,'NEEDS_APPROVAL',{reason:'ACTUAL_ORDER_ACCEPTANCE_REQUIRED'});
