 assert(version.data.immutable===true&&version.data.publishedAt&&report.data.state==='PUBLISHED'&&report.data.currentVersionId===version.id&&version.data.customerId===order.data.customerId&&version.data.siteId===order.data.siteId&&report.data.orderId===order.id&&snapshot?.order?.id===order.id&&snapshot.order.quoteId===order.data.quoteId&&snapshot.order.quoteVersion===order.data.quoteVersion&&snapshot.totalNetCents===order.data.finalNetCents,'NEEDS_APPROVAL',{reason:'CURRENT_PUBLISHED_ORDER_REPORT_REQUIRED'});
