 if(i.closureBasis==='CONTRACTUAL_ACCEPTANCE') {assert(i.acknowledgmentId,'NEEDS_APPROVAL',{reason:'ACTUAL_WORK_ACCEPTANCE_REQUIRED'});const ack=await c.tx.get('customer_acknowledgment',i.acknowledgmentId);assert(ack.data.immutable===true&&ack.data.reportVersionId===result.report.id&&ack.data.reportSha256===result.report.data.sha256&&ack.data.customerId===order.data.customerId&&ack.data.siteId===order.data.siteId&&ack.data.type==='WORK_ACCEPTANCE'&&ack.data.decision==='CONFIRMED'&&result.report.data.snapshot.documentType==='Abnahmeprotokoll','NEEDS_APPROVAL',{reason:'ACTUAL_WORK_ACCEPTANCE_REQUIRED'});}
 else assert(i.closureBasis==='DOCUMENTED_REASON'&&i.closureEvidence,'NEEDS_APPROVAL',{reason:'DOCUMENTED_CLOSURE_EVIDENCE_REQUIRED'});return result;
