const orderTransitionInput=ref.extend({status:z.enum(['CONFIRMED','SCHEDULED','IN_PROGRESS','WORK_SUBMITTED','CLIENT_REVIEW','CLOSED','PAUSED','CANCELLED','DISPUTED']),reason:text,remainingTaskIds:z.array(id).max(500).refine(a=>new Set(a).size===a.length).optional(),reviewId:id.optional(),reportVersionId:id.optional(),acknowledgmentId:id.optional(),closureBasis:z.enum(['CONTRACTUAL_ACCEPTANCE','DOCUMENTED_REASON']).optional(),closureEvidence:text.optional(),resolutionEvidence:text.optional(),disputeSubject:text.optional()});
async function transitionOrder(c:CommandContext,i:Data) {
 const order=await c.tx.get('order',i.id);if(order.data.siteId)c.requireSite(order.data.siteId);assert(!externalSalesActor(c),'ACCESS_DENIED');
 if(i.status==='WORK_SUBMITTED'&&order.data.status==='IN_PROGRESS')return submitOrder(c,i);
 const current=order.data.status;assert(!['CLOSED','CANCELLED'].includes(current)&&i.status!==current,'INVALID_STATE');const resolving=['PAUSED','DISPUTED'].includes(current);
 assert(internalSalesManager(c)||resolving&&c.actor.userId===order.data.responsibleUserId,'ACCESS_DENIED');
 if(resolving&&i.status!=='CANCELLED') {assert(i.resolutionEvidence,'NEEDS_APPROVAL',{reason:'EXPLICIT_ORDER_RESOLUTION_REQUIRED'});if(current==='PAUSED')assert(i.status===order.data.resume_state,'INVALID_STATE',{reason:'PAUSE_MUST_RESUME_PRESERVED_STAGE'});else assert(['CONFIRMED','SCHEDULED','IN_PROGRESS','WORK_SUBMITTED','CLIENT_REVIEW'].includes(i.status),'INVALID_STATE');}
 else if(!['PAUSED','DISPUTED','CANCELLED'].includes(i.status))assert(current==='WORK_SUBMITTED'&&i.status==='CLIENT_REVIEW'||current==='CLIENT_REVIEW'&&i.status==='CLOSED','INVALID_STATE');
 let fields:Data={};
 if(i.status==='PAUSED') {assert(['CONFIRMED','SCHEDULED','IN_PROGRESS','WORK_SUBMITTED','CLIENT_REVIEW'].includes(current),'INVALID_STATE');fields={resume_state:current,pause:{reason:i.reason,pausedBy:c.actor.userId,pausedAt:c.now}};}
 else if(i.status==='DISPUTED') {assert(!resolving&&i.disputeSubject,'VALIDATION_ERROR',{reason:'DISPUTE_SUBJECT_REQUIRED'});fields={disputed_from:current,dispute:{subject:i.disputeSubject,reason:i.reason,openedBy:c.actor.userId,openedAt:c.now}};}
 else if(i.status==='CANCELLED') {
  for(const reservation of await c.tx.list('schedule_reservation'))if(reservation.data.orderId===order.id&&reservation.data.status==='ACTIVE'&&date(reservation.data.endAt)>date(c.now))await c.tx.save(reservation,{...reservation.data,status:'CANCELLED',releasedAt:c.now,releaseReason:i.reason},reservation.version);
  for(const assignment of await c.tx.list('crew_assignment'))if(assignment.data.orderId===order.id&&['ASSIGNED','ACKNOWLEDGED'].includes(assignment.data.status)&&date(assignment.data.endAt)>date(c.now))await c.tx.save(assignment,{...assignment.data,status:'CANCELLED',cancelledAt:c.now,cancellationReason:i.reason},assignment.version);
  for(const notification of await c.tx.list('notification'))if(notification.data.orderId===order.id&&notification.data.status==='PENDING')await c.tx.save(notification,{...notification.data,status:'CANCELLED',reason:'ORDER_CANCELLED'},notification.version);
  fields={cancelledAt:c.now,cancelledBy:c.actor.userId,cancellationReason:i.reason};await c.tx.event('dispatch.order_cancelled',{orderId:order.id,customerId:order.data.customerId,siteId:order.data.siteId,assignmentId:order.data.assignmentId,reason:i.reason});
 } else {
  await acceptedOrderScope(c,order);await orderResponsible(c,order.data.responsibleUserId);
  if(i.status==='SCHEDULED'){const assignment=await c.tx.get('crew_assignment',order.data.assignmentId);assert(assignment.data.orderId===order.id&&assignment.data.scheduleVersion===order.data.scheduleVersion&&assignment.data.employeeIds.every((id:string)=>assignment.data.acknowledgedIds.includes(id)),'NEEDS_APPROVAL',{reason:'CURRENT_ACCEPTED_CREW_REQUIRED'});await slotConflict(c,assignment.data.employeeIds,assignment.data.startAt,assignment.data.endAt,assignment.id,order.id);await requireSkills(c,order,assignment.data.employeeIds);assert(await materialsReady(c,order.id),'NEEDS_APPROVAL',{reason:'DISPATCH_MATERIALS_NOT_READY'});}
  if(i.status==='IN_PROGRESS'){assert(order.data.firstWorkSegmentId,'INVALID_STATE',{reason:'FIRST_PERMITTED_WORK_SEGMENT_REQUIRED'});const first=await c.tx.get('time_segment',order.data.firstWorkSegmentId),task=await c.tx.get('task',first.data.taskId);assert(task.data.orderId===order.id&&first.data.siteId===order.data.siteId&&['WORKING','SERVICE_TASK'].includes(first.data.activity),'INVALID_STATE');}
  if(i.status==='WORK_SUBMITTED'){const tasks=await currentOrderTasks(c,order);remainingScope(tasks,i.remainingTaskIds??order.data.submission?.remainingTaskIds);assert(order.data.submission,'NEEDS_APPROVAL');}
  if(i.status==='CLIENT_REVIEW'||i.status==='CLOSED'){const checked=i.status==='CLOSED'?await guardOrderClosed(c,order,i):await guardClientReview(c,order,i);fields={internalReviewId:checked.review.id,clientReportVersionId:checked.report.id};if(i.status==='CLOSED')Object.assign(fields,{closedAt:c.now,closedBy:c.actor.userId,closure:{basis:i.closureBasis,reason:i.reason,evidence:i.closureEvidence,acknowledgmentId:i.acknowledgmentId,reportVersionId:checked.report.id}});}
 }
 const record=await c.tx.add('order_transition',{orderId:order.id,siteId:order.data.siteId,from:current,to:i.status,reason:i.reason,actorId:c.actor.userId,at:c.now,disputeSubject:i.disputeSubject,resolutionEvidence:i.resolutionEvidence,immutable:true});
 if(resolving)Object.assign(fields,{resume_state:null,disputed_from:null,resolution:{transitionId:record.id,from:current,to:i.status,reason:i.reason,evidence:i.resolutionEvidence,actorId:c.actor.userId,at:c.now}});
 const result=await save(c,order,{...order.data,...fields,status:i.status,transitionReason:i.reason,lastTransitionId:record.id});await c.tx.event('order.status_changed',{orderId:order.id,status:i.status,previousStatus:current,transitionId:record.id});return result;
}

