   if(e.data.delivery?.channel==='PROVIDER'&&['QUEUED','UNKNOWN','ACCEPTED_BY_PROVIDER','SENT','DELIVERED','READ'].includes(e.data.delivery.status))return e;
   assert(!e.data.delivery,'NEEDS_APPROVAL',{reason:'PROVIDER_DELIVERY_RECONCILIATION_REQUIRED'});
