const knowledgeSchema=z.object({title:text,source:z.string().url().optional(),content:text,ownerId:id,language:z.enum(['DE','UK','RU','PL','LT','EN']),validFrom:timestamp,validUntil:timestamp.optional(),visibility:z.enum(['PUBLIC','INTERNAL','PERSONAL']),siteIds:z.array(id).max(100).default([]),subjectUserId:id.optional(),supersedesId:id.optional()}).strict().refine(k=>k.visibility!=='PERSONAL'||Boolean(k.subjectUserId),'personal document owner required');
function regression(config:Data) {
 const tools=config.tools as string[];
 return [
  {id:'AI-PRICE',passed:config.pricingPolicy==='SERVER_PRICE_ONLY',evidence:'Monetary output is only produced by approved PriceBook calculator'},
  {id:'AI-LANGUAGE',passed:config.defaultLanguage==='DE'&&config.supportedLanguages.includes('DE')&&config.languagePolicy==='EXPLICIT_VERIFIED_MESSAGE_LOCALE_DE',evidence:'Explicit preference precedes verified preference, user message and locale'},
  {id:'AI-HANDOFF',passed:config.handoffPolicy==='SUPPRESS_AI_UNTIL_AUTHORIZED_RETURN'&&tools.includes('requestHumanHandoff'),evidence:'Handoff suppresses AI; explicit human return required'},
  {id:'AI-ACL',passed:config.contextPolicy==='ACL_FILTER_BEFORE_RETRIEVAL',evidence:'Knowledge ACL applies before retrieval'},
  {id:'AI-INJECTION',passed:tools.every(t=>assistantTools.options.includes(t as any)),evidence:'Tools form closed enum; prompts cannot grant permissions'},
  {id:'AI-FAILURE',passed:config.timeoutMs<=60000&&config.budgetCents>=0,evidence:'Timeout and budget use deterministic human/form fallback'},
  {id:'AI-LIMIT',passed:config.maxResponseLength<=10000&&config.supportedLanguages.length<=6,evidence:'Output length and language limits validated'},
 ];
}
async function assistantAdmin(c:CommandContext,usage=false){
 const user=await c.tx.get('user',c.actor.userId);assert(user.companyId===c.actor.companyId&&user.data.active!==false,'ACCESS_DENIED');
 const roles:string[]=user.data.roles??[],permissions=[...new Set([...roles.flatMap(role=>ROLE_PERMISSIONS[role]??[]),...(user.data.permissions??[])])];
 assert(!roles.some(role=>['CLIENT','CUSTOMER','GUEST','EXTERNAL_BAULEITER'].includes(role))&&roles.some(role=>(usage?['OWNER','DIRECTOR','OPERATIONS_MANAGER']:['OWNER','DIRECTOR','OPERATIONS_MANAGER','BOT_ADMIN']).includes(role))&&permissions.includes('assistant.manage')&&c.actor.permissions.includes('assistant.manage'),'ACCESS_DENIED');
}
function parsedStoredAssistant(e:Entity){
 const keys=Object.keys((assistantSchema as z.ZodEffects<z.ZodObject<any>>).innerType().shape);
 const input=Object.fromEntries(keys.filter(key=>e.data[key]!==undefined).map(key=>[key,e.data[key]]));
 return {...e,data:{...e.data,...assistantSchema.parse(input)}};
}
async function knowledgeAllowed(c:CommandContext,e:Entity) {
 if(e.data.status!=='APPROVED'||date(e.data.validFrom)>date(c.now)||(e.data.validUntil&&date(e.data.validUntil)<=date(c.now)))return false;
 if(e.data.visibility==='PUBLIC')return true;
 if(e.data.visibility==='PERSONAL')return e.data.subjectUserId===c.actor.userId;
 if(c.actor.roles.some(r=>['CLIENT','CUSTOMER','EXTERNAL_BAULEITER','GUEST'].includes(r)))return false;
 const internal=c.actor.roles.some(r=>['OWNER','DIRECTOR','OPERATIONS_MANAGER','INTERNAL_BAULEITER','TEAM_LEADER','EMPLOYEE','DISPATCHER','STOREKEEPER','PROCUREMENT','ACCOUNTANT','BOT_ADMIN','QUALITY_CONTROL','AUDITOR'].includes(r));
 return internal&&(!(e.data.siteIds??[]).length||c.actor.permissions.includes('scope.company')||e.data.siteIds.some((siteId:string)=>c.actor.siteIds.includes(siteId)));
}
const automationSchema=z.object({name:text,trigger:id,filters:z.record(z.union([z.string(),z.number(),z.boolean()])),action:z.enum(['REMIND','CREATE_DECISION','DRAFT_REPORT','DRAFT_QUOTE','PROPOSE_CREW','DETECT_SHORTAGE']),schedule:z.object({timezone:z.literal('Europe/Berlin').default('Europe/Berlin'),cron:automationCronSchema.optional()}).strict().optional(),ownerId:id,scope:z.object({siteIds:z.array(id).max(100).default([]),customerIds:z.array(id).max(100).default([])}).strict(),cooldownSeconds:nonnegative.max(604800).default(300),maxAttempts:positive.max(10).default(3),activeFrom:timestamp,parameters:z.record(z.unknown()).default({})}).strict();
function matches(rule:Data,event:Data) {return rule.trigger===event.type&&Object.entries(rule.filters).every(([key,value])=>event.data?.[key]===value)&&(!rule.scope.siteIds.length||rule.scope.siteIds.includes(event.data?.siteId))&&(!rule.scope.customerIds.length||rule.scope.customerIds.includes(event.data?.customerId));}
async function authorizeAutomation(c:CommandContext,rule:Entity):Promise<Actor> {
 assert(typeof c.authorizeAutomationRule==='function','ACCESS_DENIED',{reason:'AUTOMATION_AUTHORIZATION_REQUIRED'});
 const owner=await c.authorizeAutomationRule(rule);
 assert(owner?.userId===rule.data.ownerId&&owner.companyId===rule.companyId&&rule.companyId===c.actor.companyId,'ACCESS_DENIED',{reason:'AUTOMATION_OWNER_AUTHORIZATION_MISMATCH'});
 return owner;
}
async function automationEventScope(c:CommandContext,rule:Entity,event:Data) {
 const data=event.data??{},siteIds:string[]=rule.data.scope.siteIds,customerIds:string[]=rule.data.scope.customerIds;
 for(const field of ['siteId','customerId','orderId'])assert(data[field]===undefined||(typeof data[field]==='string'&&data[field].length>0&&data[field].length<=100),'ACCESS_DENIED',{reason:'AUTOMATION_EVENT_SCOPE_INVALID'});
 assert((!siteIds.length||siteIds.includes(data.siteId))&&(!customerIds.length||customerIds.includes(data.customerId)),'ACCESS_DENIED',{reason:'AUTOMATION_EVENT_OUTSIDE_SCOPE'});
 if(data.orderId!==undefined){const order=await c.tx.get('order',data.orderId),orderSite=order.data.siteId??order.data.site_id,orderCustomer=order.data.customerId??order.data.customer_id;assert(order.companyId===rule.companyId&&(!siteIds.length||siteIds.includes(orderSite))&&(!customerIds.length||customerIds.includes(orderCustomer))&&(data.siteId===undefined||data.siteId===orderSite)&&(data.customerId===undefined||data.customerId===orderCustomer),'ACCESS_DENIED',{reason:'AUTOMATION_ORDER_OUTSIDE_SCOPE'});}
}
