// Customer observations are separate from report versions, task reviews and contractual acceptance.
const issueLanguages=z.enum(['DE','UK','RU','PL','LT','EN']);
const issueClassification=z.enum(['DEFECT','ADDITIONAL_WORK','NEW_SCOPE','CLARIFICATION']);
const issueCreateSchema=z.object({
 siteId:id,orderId:id.optional(),locationId:id.optional(),taskId:id.optional(),
 photoIds:z.array(id).max(30).default([]).refine(ids=>new Set(ids).size===ids.length,'duplicate photo IDs'),
 description:text,language:issueLanguages.default('DE'),externalKey:id,
 severity:z.enum(['LOW','NORMAL','HIGH','CRITICAL']).default('NORMAL'),dueAt:timestamp.optional(),
}).strict().refine(i=>Boolean(i.locationId||i.taskId||i.photoIds.length),'specific location, task or photo required');
const externalIssueActor=(c:CommandContext)=>c.actor.roles.some(r=>['CLIENT','CUSTOMER','EXTERNAL_BAULEITER','GUEST'].includes(r));
const reviewIssueActor=(c:CommandContext)=>!externalIssueActor(c)&&c.actor.roles.some(r=>['OWNER','DIRECTOR','OPERATIONS_MANAGER','INTERNAL_BAULEITER','QUALITY_CONTROL'].includes(r));
function issueExpected(c:CommandContext,e:Entity){assert(c.expectedVersion===undefined||c.expectedVersion===e.version,'VERSION_CONFLICT');}
async function issueCustomerScope(c:CommandContext,customerId:string,siteId:string){
 const membership=(await c.tx.list('customer_membership')).some(m=>m.data.userId===c.actor.userId&&m.data.customerId===customerId&&m.data.active===true&&!m.data.revokedAt&&(!m.data.expiresAt||date(m.data.expiresAt)>date(c.now))&&(m.data.permissions??[]).includes('VIEW')&&(!(m.data.siteIds??[]).length||m.data.siteIds.includes(siteId)));
 assert(membership,'NOT_FOUND_SAFE');
}
async function issueAccess(c:CommandContext,e:Entity){
 if(e.data.state==='DRAFT')assert(e.data.createdBy===c.actor.userId,'NOT_FOUND_SAFE');
 if(externalIssueActor(c))await issueCustomerScope(c,e.data.customerId,e.data.siteId);
 else {assert(reviewIssueActor(c),'ACCESS_DENIED');c.requireSite(e.data.siteId);}
}
export function publicIssueProjection(e:Entity):Entity {
 const d=e.data;
 return {...e,data:{number:d.number,siteId:d.siteId,customerId:d.customerId,orderId:d.orderId,locationId:d.locationId,taskId:d.taskId,photoIds:d.photoIds,description:d.description,language:d.language,severity:d.severity,state:d.state,classification:d.classification??null,publicResponse:d.publicResponse??null,dueAt:d.dueAt??null,cycle:d.cycle,workStatus:d.workStatus??null,submittedAt:d.submittedAt??null,resolvedAt:d.resolvedAt??null,publicHistory:d.publicHistory??[]}};
}
async function issueResult(c:CommandContext,e:Entity){
 if(e.data.linkedTaskId){const work=await c.tx.get('task',e.data.linkedTaskId);e={...e,data:{...e.data,workStatus:work.data.state}};}
 return externalIssueActor(c)?publicIssueProjection(e):e;
}
async function issueReferences(c:CommandContext,input:z.infer<typeof issueCreateSchema>){
 const site=await c.tx.get('site',input.siteId);assert(site.data.customerId,'NOT_FOUND_SAFE');
 await issueCustomerScope(c,site.data.customerId,site.id);
 let task:Entity|undefined;
 if(input.taskId){task=await c.tx.get('task',input.taskId);assert(task.data.siteId===site.id,'NOT_FOUND_SAFE');
  const published=(await c.tx.list('report_version')).some(r=>r.data.immutable===true&&r.data.publishedAt&&r.data.siteId===site.id&&r.data.customerId===site.data.customerId&&(r.data.snapshot?.taskRows??[]).some((row:Data)=>(row.taskId??row.id)===task!.id));
  assert(task.data.clientVisible===true||published,'NOT_FOUND_SAFE');
 }
 const orderId=input.orderId??task?.data.orderId;
 if(orderId){const order=await c.tx.get('order',orderId);assert(order.data.siteId===site.id&&order.data.customerId===site.data.customerId,'NOT_FOUND_SAFE');if(task?.data.orderId)assert(task.data.orderId===order.id,'NOT_FOUND_SAFE');}
 if(input.locationId){const location=await c.tx.get('location',input.locationId);assert(location.data.siteId===site.id,'NOT_FOUND_SAFE');if(task?.data.locationId)assert(task.data.locationId===location.id,'NOT_FOUND_SAFE');}
 for(const photoId of input.photoIds){const media=await c.tx.get('media_asset',photoId);assert(media.data.siteId===site.id&&String(media.data.mimeType).startsWith('image/')&&media.data.visibility!=='CONFIDENTIAL','NOT_FOUND_SAFE');
  const own=media.data.uploadedBy===c.actor.userId&&['RECEIVED','APPROVED_FOR_CLIENT'].includes(media.data.state);
  const clientCopy=media.data.visibility==='CLIENT_AFTER_APPROVAL'&&media.data.state==='APPROVED_FOR_CLIENT'&&media.data.clientBlobKey;
  assert(own||clientCopy,'NOT_FOUND_SAFE');if(task&&media.data.taskId)assert(media.data.taskId===task.id,'NOT_FOUND_SAFE');if(input.locationId&&(media.data.locationNodeId??media.data.locationId))assert((media.data.locationNodeId??media.data.locationId)===input.locationId,'NOT_FOUND_SAFE');
 }
 return {site,task,orderId};
}
async function issueOwner(c:CommandContext,site:Entity,preferred?:string){
 const users=await c.tx.list('user');const valid=(u:Entity)=>u.data.active!==false&&!u.data.roles?.some((r:string)=>['CLIENT','CUSTOMER','EXTERNAL_BAULEITER','GUEST'].includes(r))&&u.data.roles?.some((r:string)=>['OWNER','DIRECTOR','OPERATIONS_MANAGER','INTERNAL_BAULEITER','QUALITY_CONTROL'].includes(r))&&((u.data.siteIds??[]).includes(site.id)||(u.data.permissions??[]).includes('scope.company')||(u.data.roles??[]).some((role:string)=>(ROLE_PERMISSIONS[role]??[]).includes('scope.company')));
 if(preferred){const user=await c.tx.get('user',preferred);assert(valid(user),'ACCESS_DENIED');return user.id;}
 return users.find(u=>valid(u)&&(site.data.managerIds??[]).includes(u.id))?.id??users.find(u=>valid(u)&&u.data.roles.includes('INTERNAL_BAULEITER'))?.id??users.find(valid)?.id??'UNASSIGNED';
}
async function openIssue(c:CommandContext,e:Entity){
 const ownerId=await issueOwner(c,await c.tx.get('site',e.data.siteId));
 const saved=await c.tx.save(e,{...e.data,state:'OPEN',ownerId,submittedAt:c.now,publicHistory:[...(e.data.publicHistory??[]),{state:'OPEN',at:c.now,description:e.data.description,language:e.data.language,cycle:e.data.cycle}]},e.version);
 await addDecision(c,{reason:'CUSTOMER_ISSUE',issueId:e.id,siteId:e.data.siteId,orderId:e.data.orderId,ownerId,dueAt:e.data.dueAt,sources:[e.id],actions:['RETURN','DELEGATE'],summaryDE:`Kundenhinweis ${e.data.number}. Originalsprache: ${e.data.language}. Fachliche Qualifizierung erforderlich.`},`issue:${e.id}:cycle:${e.data.cycle}`);
 await c.tx.event('issue.opened',{issueId:e.id,siteId:e.data.siteId,customerId:e.data.customerId,ownerId,cycle:e.data.cycle,severity:e.data.severity});return saved;
}
async function createIssue(c:CommandContext,input:z.infer<typeof issueCreateSchema>,draft:boolean){
 assert(externalIssueActor(c),'ACCESS_DENIED');const {site,task,orderId}=await issueReferences(c,input);
 const normalized={...input,orderId:orderId??null,locationId:input.locationId??task?.data.locationId??null};
 const old=(await c.tx.list('issue')).find(e=>e.data.createdBy===c.actor.userId&&e.data.siteId===site.id&&e.data.externalKey===input.externalKey);
 if(old){await issueAccess(c,old);assert(JSON.stringify(old.data.originalInput)===JSON.stringify(normalized),'VERSION_CONFLICT',{reason:'ISSUE_KEY_REUSED'});if(!draft&&old.data.state==='DRAFT')return issueResult(c,await openIssue(c,old));return issueResult(c,old);}
 const issue=await c.tx.add('issue',{...normalized,customerId:site.data.customerId,createdBy:c.actor.userId,originalInput:normalized,originalTaskSnapshot:task?{taskId:task.id,version:task.version,state:task.data.state,quantityMilli:task.data.acceptedQuantityMilli}:null,state:'DRAFT',cycle:1,history:[],publicHistory:[],reopenRequests:[],createdAt:c.now});
 const numbered=await c.tx.save(issue,{...issue.data,number:`KNB-I-${issue.id}`},issue.version);
 return issueResult(c,draft?numbered:await openIssue(c,numbered));
}
const qualifyIssueSchema=ref.extend({classification:issueClassification,publicResponse:text,internalReason:text,ownerId:id.optional(),dueAt:timestamp.optional(),assigneeIds:z.array(id).max(100).default([]).refine(ids=>new Set(ids).size===ids.length),workTitle:z.string().trim().min(1).max(250).optional(),plannedQuantityMilli:positive.optional(),plannedMinutes:nonnegative.default(0),changeOrderId:id.optional()}).strict();
async function issueStaff(c:CommandContext,idValue:string){const e=await c.tx.get('issue',idValue);assert(reviewIssueActor(c),'ACCESS_DENIED');await issueAccess(c,e);issueExpected(c,e);return e;}
async function issueChange(c:CommandContext,e:Entity,changeOrderId:string){const change=await c.tx.get('change_order',changeOrderId);assert(e.data.orderId&&change.data.orderId===e.data.orderId&&change.data.customerId===e.data.customerId,'NOT_FOUND_SAFE');return change;}
async function runIssueWork(c:CommandContext,name:string,input:Data){const def=operationsCommands[name]!;assert(c.actor.permissions.includes(def.permission),'ACCESS_DENIED');return def.handler({...c,expectedVersion:undefined},def.schema.parse(input));}
async function finishIssueDecision(c:CommandContext,e:Entity,resolution:string){for(const decision of await c.tx.list('decision'))if(decision.data.issueId===e.id&&decision.data.status==='OPEN')await c.tx.save(decision,{...decision.data,status:'RESOLVED',resolution,resolvedAt:c.now,resolvedBy:c.actor.userId},decision.version);}
Object.assign(commerceCommands,{
 'issue.draft':command('issue.create',issueCreateSchema,async(c,i)=>createIssue(c,i,true)),
 'issue.create':command('issue.create',issueCreateSchema,async(c,i)=>createIssue(c,i,false)),
 'issue.context':command('issue.read',z.object({siteId:id}).strict(),async(c,i)=>{
  const site=await c.tx.get('site',i.siteId);assert(site.data.customerId,'NOT_FOUND_SAFE');
  if(externalIssueActor(c))await issueCustomerScope(c,site.data.customerId,site.id);else {assert(reviewIssueActor(c),'ACCESS_DENIED');c.requireSite(site.id);}
  const publishedIds=new Set<string>();for(const report of await c.tx.list('report_version'))if(report.data.siteId===site.id&&report.data.customerId===site.data.customerId&&report.data.immutable===true&&report.data.publishedAt)for(const row of report.data.snapshot?.taskRows??[])if(typeof(row.taskId??row.id)==='string')publishedIds.add(row.taskId??row.id);
  const locations=(await c.tx.list('location')).filter(location=>location.data.siteId===site.id&&location.data.active!==false).map(location=>({id:location.id,nodeType:location.data.nodeType,code:location.data.code,name:location.data.name,parentId:location.data.parentId??null,floorLabelDe:location.data.floorLabelDe??null}));
  const tasks=(await c.tx.list('task')).filter(task=>task.data.siteId===site.id&&(!externalIssueActor(c)||task.data.clientVisible===true||publishedIds.has(task.id))).map(task=>({id:task.id,title:task.data.title,state:task.data.state,locationId:task.data.locationId??null,orderId:task.data.orderId??null}));
  return {siteId:site.id,locations,tasks};
 }),
 'issue.submit':command('issue.create',ref,async(c,i)=>{const e=await c.tx.get('issue',i.id);assert(externalIssueActor(c)&&e.data.createdBy===c.actor.userId,'NOT_FOUND_SAFE');await issueAccess(c,e);issueExpected(c,e);if(e.data.state==='OPEN')return issueResult(c,e);assert(e.data.state==='DRAFT','INVALID_STATE');await issueReferences(c,e.data.originalInput);return issueResult(c,await openIssue(c,e));}),
 'issue.get':command('issue.read',ref,async(c,i)=>{const e=await c.tx.get('issue',i.id);await issueAccess(c,e);return issueResult(c,e);}),
 'issue.list':command('issue.read',z.object({siteId:id.optional()}).strict(),async(c,i)=>{const items=[];for(const issue of await c.tx.list('issue')){if(i.siteId&&issue.data.siteId!==i.siteId)continue;try{await issueAccess(c,issue);items.push(await issueResult(c,issue));}catch(error){if(!(error instanceof DomainError)||!['NOT_FOUND_SAFE','ACCESS_DENIED'].includes(error.code))throw error;}}return {items};}),
 'issue.qualify':command('task.review',qualifyIssueSchema,async(c,i)=>{
  const e=await issueStaff(c,i.id);assert(['OPEN','TRIAGED','IN_PROGRESS'].includes(e.data.state),'INVALID_STATE');
  const {id:issueId,...qualification}=i;
  if(e.data.qualification){assert(JSON.stringify(e.data.qualification)===JSON.stringify(qualification),'VERSION_CONFLICT',{reason:'ISSUE_ALREADY_QUALIFIED'});return e;}
  const site=await c.tx.get('site',e.data.siteId),ownerId=await issueOwner(c,site,i.ownerId??c.actor.userId);
  if(i.dueAt)assert(date(i.dueAt)>date(c.now),'VALIDATION_ERROR');
  let linkedDefectId:string|null=null,linkedTaskId:string|null=null,decisionId:string|null=null;
  if(i.changeOrderId){assert(i.classification==='NEW_SCOPE','VALIDATION_ERROR');await issueChange(c,e,i.changeOrderId);}
  if(i.classification==='DEFECT'){
   assert(e.data.taskId,'NEEDS_APPROVAL',{reason:'TASK_REQUIRED_FOR_DEFECT'});
   const defect=await runIssueWork(c,'defect.create',{taskId:e.data.taskId,externalKey:`issue:${e.id}:${e.data.cycle}`,description:e.data.description,severity:e.data.severity,dueAt:i.dueAt??e.data.dueAt,photoIds:e.data.photoIds});linkedDefectId=defect.id;
   if(i.assigneeIds.length){const work=await runIssueWork(c,'defect.rework',{defectId:defect.id,assigneeIds:i.assigneeIds,title:i.workTitle,plannedQuantityMilli:i.plannedQuantityMilli,plannedMinutes:i.plannedMinutes,responsibilityDecision:i.internalReason});linkedTaskId=work.id;}
  }else if(i.classification==='ADDITIONAL_WORK'){
   assert(e.data.taskId&&i.plannedQuantityMilli,'NEEDS_APPROVAL',{reason:'CONFIRMED_REMAINING_SCOPE_REQUIRED'});const original=await c.tx.get('task',e.data.taskId);
   const remaining=Math.max(0,original.data.plannedQuantityMilli-original.data.acceptedQuantityMilli);assert(i.plannedQuantityMilli<=remaining,'NEEDS_APPROVAL',{reason:'REMAINING_CONTRACT_SCOPE_EXCEEDED'});
   const work=await runIssueWork(c,'task.create',{siteId:e.data.siteId,orderId:e.data.orderId??undefined,locationId:e.data.locationId??undefined,title:i.workTitle??`Fortsetzung: ${original.data.title}`,description:e.data.description,originalLanguage:e.data.language.toLowerCase(),unit:original.data.unit,plannedQuantityMilli:i.plannedQuantityMilli,plannedMinutes:i.plannedMinutes,assigneeIds:i.assigneeIds,dueAt:i.dueAt,completionKind:'CONTINUATION',billingScope:'CONTRACT',clientVisible:true});
   const linked=await c.tx.save(work,{...work.data,sourceTaskId:original.id,issueId:e.id},work.version);linkedTaskId=linked.id;
  }else if(i.classification==='NEW_SCOPE'){
   const decision=await addDecision(c,{reason:'CUSTOMER_ADDITIONAL_SCOPE',issueId:e.id,siteId:e.data.siteId,orderId:e.data.orderId,ownerId,sources:[e.id],actions:['APPROVE','RETURN','DELEGATE'],summaryDE:`Kundenhinweis ${e.data.number}: neuer Leistungsumfang benötigt gesondertes Angebot/Nachtrag.`,changeOrderId:i.changeOrderId},`issue-new-scope:${e.id}:${e.data.cycle}`);decisionId=decision.id;
  }else assert(!i.assigneeIds.length&&!i.plannedQuantityMilli,'VALIDATION_ERROR',{reason:'CLARIFICATION_HAS_NO_WORK'});
  const state=linkedTaskId?'IN_PROGRESS':'TRIAGED';
  const data={...e.data,state,classification:i.classification,publicResponse:i.publicResponse,qualification,ownerId,dueAt:i.dueAt??e.data.dueAt,linkedDefectId,linkedTaskId,changeOrderId:i.changeOrderId??null,newScopeDecisionId:decisionId,qualifiedBy:c.actor.userId,qualifiedAt:c.now,history:[...e.data.history,{action:'QUALIFIED',at:c.now,actorId:c.actor.userId,internalReason:i.internalReason,classification:i.classification,cycle:e.data.cycle,linkedDefectId,linkedTaskId}],publicHistory:[...e.data.publicHistory,{state,classification:i.classification,publicResponse:i.publicResponse,at:c.now,cycle:e.data.cycle}]};
  const result=await save(c,e,data);for(const decision of await c.tx.list('decision'))if(decision.data.issueId===e.id&&decision.data.reason==='CUSTOMER_ISSUE'&&decision.data.status==='OPEN')await c.tx.save(decision,{...decision.data,status:'RESOLVED',resolution:'QUALIFIED',resolvedAt:c.now,resolvedBy:c.actor.userId},decision.version);
  await c.tx.event('issue.qualified',{issueId:e.id,siteId:e.data.siteId,customerId:e.data.customerId,state,classification:i.classification,cycle:e.data.cycle});return result;
 }),
 'issue.link_work':command('task.review',ref.extend({taskId:id.optional(),defectId:id.optional(),changeOrderId:id.optional(),publicResponse:text,internalReason:text}).strict().refine(i=>Boolean(i.taskId||i.defectId||i.changeOrderId),'linked work or change required'),async(c,i)=>{
  const e=await issueStaff(c,i.id);assert(['TRIAGED','IN_PROGRESS'].includes(e.data.state),'INVALID_STATE');
  let defect:Entity|undefined;if(i.defectId){defect=await c.tx.get('defect',i.defectId);assert(e.data.classification==='DEFECT'&&defect.data.siteId===e.data.siteId&&defect.data.taskId===e.data.taskId&&defect.data.externalKey===`issue:${e.id}:${e.data.cycle}`,'NOT_FOUND_SAFE');}
  const defectId=i.defectId??e.data.linkedDefectId,changeId=i.changeOrderId??e.data.changeOrderId;
  if(changeId){assert(e.data.classification==='NEW_SCOPE','INVALID_STATE');await issueChange(c,e,changeId);}
  assert(!e.data.linkedTaskId||!i.taskId||e.data.linkedTaskId===i.taskId,'VERSION_CONFLICT',{reason:'LINKED_WORK_CANNOT_BE_REPLACED'});
  if(i.taskId){const work=await c.tx.get('task',i.taskId);assert(work.data.siteId===e.data.siteId,'NOT_FOUND_SAFE');if(e.data.classification==='DEFECT'){const linkedDefect=await c.tx.get('defect',defectId);assert(work.data.completionKind==='REWORK'&&work.data.defectId===defectId&&work.data.sourceTaskId===e.data.taskId&&linkedDefect.data.reworkTaskId===work.id,'NOT_FOUND_SAFE');}
   else if(e.data.classification==='ADDITIONAL_WORK')assert(work.data.completionKind==='CONTINUATION'&&work.data.sourceTaskId===e.data.taskId&&work.data.issueId===e.id,'NOT_FOUND_SAFE');
   else if(e.data.classification==='NEW_SCOPE'){const change=await issueChange(c,e,changeId);assert(change.data.status==='ACCEPTED'&&work.data.orderId===e.data.orderId&&work.data.changeOrderId===change.id&&work.data.completionKind==='ADDITIONAL_SCOPE','NEEDS_APPROVAL');}
   else throw new DomainError('INVALID_STATE');
  }
  const state=(i.taskId??e.data.linkedTaskId)?'IN_PROGRESS':'TRIAGED';const result=await save(c,e,{...e.data,state,linkedDefectId:defectId??null,linkedTaskId:i.taskId??e.data.linkedTaskId,changeOrderId:changeId??null,publicResponse:i.publicResponse,history:[...e.data.history,{action:'LINKED_WORK',actorId:c.actor.userId,at:c.now,internalReason:i.internalReason,cycle:e.data.cycle}],publicHistory:[...e.data.publicHistory,{state,publicResponse:i.publicResponse,at:c.now,cycle:e.data.cycle}]});await c.tx.event('issue.work_linked',{issueId:e.id,siteId:e.data.siteId,customerId:e.data.customerId,state,cycle:e.data.cycle});return result;
 }),
 'issue.resolve':command('task.review',ref.extend({publicResponse:text,reason:text,resolution:z.enum(['COMPLETED','ANSWERED','NO_ACTION_AGREED']).default('COMPLETED'),evidenceReference:z.string().min(8).max(2000).optional()}).strict(),async(c,i)=>{
  const e=await issueStaff(c,i.id);if(e.data.state==='RESOLVED'){assert(e.data.resolution===i.resolution&&e.data.publicResponse===i.publicResponse,'VERSION_CONFLICT');return e;}assert(['TRIAGED','IN_PROGRESS'].includes(e.data.state),'INVALID_STATE');
  if(i.resolution==='NO_ACTION_AGREED')assert(i.evidenceReference,'NEEDS_APPROVAL',{reason:'CUSTOMER_AGREEMENT_EVIDENCE_REQUIRED'});
  else if(e.data.classification==='CLARIFICATION')assert(i.resolution==='ANSWERED','INVALID_STATE');
  else {assert(i.resolution==='COMPLETED'&&e.data.linkedTaskId,'NEEDS_APPROVAL',{reason:'LINKED_ACCEPTED_WORK_REQUIRED'});const work=await c.tx.get('task',e.data.linkedTaskId);assert(work.data.state==='ACCEPTED','NEEDS_APPROVAL',{reason:'WORK_NOT_ACCEPTED'});if(e.data.classification==='DEFECT'){const defect=await c.tx.get('defect',e.data.linkedDefectId);assert(defect.data.state==='CLOSED','NEEDS_APPROVAL');}if(e.data.classification==='NEW_SCOPE'){const change=await issueChange(c,e,e.data.changeOrderId);assert(change.data.status==='ACCEPTED','NEEDS_APPROVAL');}}
  const result=await save(c,e,{...e.data,state:'RESOLVED',publicResponse:i.publicResponse,resolution:i.resolution,resolutionEvidence:i.evidenceReference??null,resolvedAt:c.now,resolvedBy:c.actor.userId,history:[...e.data.history,{action:'RESOLVED',actorId:c.actor.userId,at:c.now,reason:i.reason,evidenceReference:i.evidenceReference,cycle:e.data.cycle}],publicHistory:[...e.data.publicHistory,{state:'RESOLVED',publicResponse:i.publicResponse,at:c.now,cycle:e.data.cycle}]});await finishIssueDecision(c,e,'ISSUE_RESOLVED');await c.tx.event('issue.resolved',{issueId:e.id,siteId:e.data.siteId,customerId:e.data.customerId,cycle:e.data.cycle});return result;
 }),
 'issue.reopen':command('issue.create',ref.extend({description:text,externalKey:id}).strict(),async(c,i)=>{
  const e=await c.tx.get('issue',i.id);assert(externalIssueActor(c),'ACCESS_DENIED');await issueAccess(c,e);issueExpected(c,e);
  const old=e.data.reopenRequests.find((r:Data)=>r.externalKey===i.externalKey);if(old){assert(old.description===i.description,'VERSION_CONFLICT');return issueResult(c,e);}assert(e.data.state==='RESOLVED','INVALID_STATE');assert(e.data.reopenRequests.length<100,'VALIDATION_ERROR');
  const updated=await save(c,e,{...e.data,state:'DRAFT',cycle:e.data.cycle+1,description:i.description,classification:null,qualification:null,linkedTaskId:null,linkedDefectId:null,changeOrderId:null,publicResponse:null,resolvedAt:null,reopenRequests:[...e.data.reopenRequests,{externalKey:i.externalKey,description:i.description,at:c.now,actorId:c.actor.userId}],history:[...e.data.history,{action:'REOPENED',actorId:c.actor.userId,at:c.now,description:i.description,previousCycle:e.data.cycle}],publicHistory:[...e.data.publicHistory,{state:'REOPENED',description:i.description,at:c.now,cycle:e.data.cycle+1}]});return issueResult(c,await openIssue(c,updated));
 }),
});

// Customer actions retain a separate own-lead permission; assistant tools never
// grant staff lead.manage to a client or infer customer membership from a phone.
for (const [ownName,staffName,reference] of [
 ['lead.own_qualify','lead.qualify','id'],
 ['lead.own_handoff','lead.handoff','id'],
 ['site_visit.own_create','site_visit.create','leadId'],
] as const){
 const original=commerceCommands[staffName]!;
 commerceCommands[ownName]={...original,permission:'lead.manage_own',handler:async(c,i)=>{
  const lead=await c.tx.get('lead',i[reference]);assert(lead.data.ownerUserId===c.actor.userId,'NOT_FOUND_SAFE');
  return original.handler(c,i);
 }};
}
